async function loadSecretsFromVault() {
  const client = vault({
    apiVersion: 'v1',
    endpoint: process.env.VAULT_ADDR,
    token: process.env.VAULT_TOKEN // This should be temporary token only
  });

  const { data } = await client.read('secret/data/application');
  return data.data;
}
```

### **Option 3: Azure Key Vault**

