```javascript
// secrets-loader.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const logger = require('./logger');

class SecureSecretsLoader {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
    this.secrets = null;
    this.cacheExpiry = 5 * 60 * 1000; // 5 minutes
    this.lastFetch = null;
  }

  async loadSecrets() {
    // Return cached secrets if still valid
    if (this.secrets && this.lastFetch && 
        (Date.now() - this.lastFetch) < this.cacheExpiry) {
      return this.secrets;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: process.env.SECRET_ARN || 'prod/app/secrets'
      });

      const response = await this.client.send(command);
      const secrets = JSON.parse(response.SecretString);

      // Validate no canaries in production
      if (process.env.NODE_ENV === 'production') {
        this.validateNoCanaries(secrets);
      }

      this.secrets = secrets;
      this.lastFetch = Date.now();

      logger.info('Secrets loaded successfully');
      return secrets;

    } catch (error) {
      logger.error('Failed to load secrets', { error: error.message });

      // In production, crash rather than run with missing secrets
      if (process.env.NODE_ENV === 'production') {
        process.exit(1);
      }

      // In development, load from .env (but warn)
      logger.warn('Loading secrets from .env file - NOT FOR PRODUCTION');
      return this.loadFromEnvLocal();
    }
  }

  validateNoCanaries(secrets) {
    const canaryPatterns = ['CANARY', 'fake', 'test', 'example'];

    for (const [key, value] of Object.entries(secrets)) {
      if (typeof value === 'string') {
        const hasCanary = canaryPatterns.some(pattern => 
          value.toUpperCase().includes(pattern.toUpperCase())
        );

        if (hasCanary) {
          throw new Error(`Canary credential detected in secret: ${key}`);
        }
      }
    }
  }

  loadFromEnvLocal() {
    require('dotenv').config({ path: '.env.local' });
    return {
      DATABASE_URL: process.env.DATABASE_URL,
      JWT_SECRET: process.env.JWT_SECRET,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      // ... other secrets
    };
  }

  // Secure getter that prevents logging
  get(key) {
    if (!this.secrets) {
      throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }
    return this.secrets[key];
  }
}

// Singleton instance
module.exports = new SecureSecretsLoader();
