## **RECOMMENDED SECRETS MANAGEMENT STRATEGIES**

### **Option 1: Cloud Secrets Manager (BEST for Production)**

#### **AWS Secrets Manager**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = new Map();
    this.ttl = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = JSON.parse(response.SecretString);

      // Update cache
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error('Secrets retrieval failed');
    }
  }
}

// Usage
const secrets = new SecretsManager();

app.get('/database-query', async (req, res) => {
  try {
    const dbSecrets = await secrets.getSecret('prod/database/credentials');
    // Use dbSecrets.username, dbSecrets.password
    // They're cached and automatically rotated by AWS
  } catch (error) {
    res.status(500).json({ error: 'Database unavailable' });
  }
});
```

