## **SECURE SECRETS LOADING PATTERN**

Here's the complete pattern you should implement:

```javascript
// config/secrets.js
class SecureSecretsManager {
  constructor() {
    this.secrets = null;
    this.isLoaded = false;
  }

  async initialize() {
    if (this.isLoaded) return;

    try {
      // Determine environment
      const environment = process.env.NODE_ENV || 'development';

      if (environment === 'production') {
        // Load from cloud secrets manager
        this.secrets = await this.loadFromCloud();
      } else if (environment === 'staging') {
        // Load from staging vault
        this.secrets = await this.loadFromVault();
      } else {
        // Development - load from environment variables only
        this.secrets = this.loadFromEnv();
      }

      // Verify required secrets
      this.validateSecrets();

      this.isLoaded = true;
      console.log('Secrets loaded successfully');
    } catch (error) {
      console.error('Failed to initialize secrets:', error);
      process.exit(1); // Fail fast if secrets can't be loaded
    }
  }

  async loadFromCloud() {
    // Example: AWS Secrets Manager
    const secrets = {};

    // Load database credentials
    const dbSecret = await getSecretFromAWS('prod/database');
    secrets.database = {
      url: `postgres://${dbSecret.username}:${dbSecret.password}@${dbSecret.host}/${dbSecret.dbname}`
    };

    // Load API keys
    secrets.apiKeys = {
      stripe: await getSecretFromAWS('prod/stripe-key'),
      sendgrid: await getSecretFromAWS('prod/sendgrid-key')
    };

    return secrets;
  }

  loadFromEnv() {
    // Only for development - validates required vars exist
    const required = ['DATABASE_URL', 'API_KEY'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }

    return {
      database: { url: process.env.DATABASE_URL },
      apiKeys: { 
        stripe: process.env.STRIPE_KEY,
        sendgrid: process.env.SENDGRID_KEY
      }
    };
  }

  validateSecrets() {
    const required = ['database', 'apiKeys.stripe', 'apiKeys.sendgrid'];

    for (const path of required) {
      const keys = path.split('.');
      let current = this.secrets;

      for (const key of keys) {
        if (!current || !current[key]) {
          throw new Error(`Missing required secret: ${path}`);
        }
        current = current[key];
      }
    }
  }

  get(path) {
    if (!this.isLoaded) {
      throw new Error('Secrets not initialized. Call initialize() first.');
    }

    const keys = path.split('.');
    let current = this.secrets;

    for (const key of keys) {
      if (!current || !current[key]) {
        throw new Error(`Secret not found: ${path}`);
      }
      current = current[key];
    }

    return current;
  }
}

// Singleton instance
const secretsManager = new SecureSecretsManager();

module.exports = secretsManager;
```

